
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"LuckyCoinAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		    var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.myx.mmp!=undefined){
			
			if(gameController.pzy!=parseInt(tmpMess[1])){
				
			gameController.pzy=parseInt(tmpMess[1]);	
			gameController.myx.mmp.boi("creditd", "#zah", [gameController.mfd(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
